public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a graph to represent the n-interesting space
    Map<String, Set<String>> graph = new HashMap<>();
    for (int[] path : paths) {
        String from = path[0] + "," + path[1];
        String to = path[2] + "," + path[3];
        graph.computeIfAbsent(from, k -> new HashSet<>()).add(to);
        graph.computeIfAbsent(to, k -> new HashSet<>()).add(from);
    }

    // Helper function to perform BFS
    class BFSHelper {
        Set<String> visited = new HashSet<>();

        boolean canTravel(String start, String end) {
            if (start.equals(end)) {
                return true;
            }
            Queue<String> queue = new LinkedList<>();
            queue.add(start);
            visited.add(start);

            while (!queue.isEmpty()) {
                String current = queue.poll();
                for (String neighbor : graph.getOrDefault(current, Set.of())) {
                    if (!visited.contains(neighbor)) {
                        if (neighbor.equals(end)) {
                            return true;
                        }
                        queue.add(neighbor);
                        visited.add(neighbor);
                    }
                }
            }
            return false;
        }
    }

    // Convert start and end coordinates to string format
    String startStr = start[0] + "," + start[1];
    String endStr = end[0] + "," + end[1];

    // Perform BFS to check if there is a path from start to end
    BFSHelper helper = new BFSHelper();
    if (helper.canTravel(startStr, endStr)) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

public static String appx(String word1, String word2) {
        if (word1 == null || word2 == null) {
            throw new IllegalArgumentException("Input strings cannot be null");
        }

        Set<Character> set1 = new HashSet<>();
        for (char c : word1.toCharArray()) {
            set1.add(c);
        }

        Set<Character> set2 = new HashSet<>();
        for (char c : word2.toCharArray()) {
            set2.add(c);
        }

        int commonLetters = 0;
        for (char c : set1) {
            if (set2.contains(c)) {
                commonLetters++;
            }
        }

        int totalLength = word1.length() + word2.length();
        int gcd = gcd(commonLetters, totalLength);

        return String.format("appx(%s, %s) = %d/%d", word1, word2, commonLetters / gcd, totalLength / gcd);
    }

public static String appx(String word1, String word2) {
        String common = "";
        for (char c : word1.toCharArray()) {
            if (word2.indexOf(c) != -1) {
                if (common.indexOf(c) == -1) {
                    common += c;
                }
            }
        }
        int numerator = common.length();
        int denominator = word1.length() + word2.length() - numerator;
        return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
    }

