    }

    word1 = word1.toUpperCase();
    word2 = word2.toUpperCase();

    int commonCount = 0;
    int unionCount = 0;

    for (char c : word1.toCharArray()) {
        if (word2.indexOf(c) >= 0) {
            commonCount++;
        }
        unionCount++;
    }

    for (char c : word2.toCharArray()) {
        if (!word1.contains(String.valueOf(c))) {
            unionCount++;
        }
    }

    long gcd = gcd(commonCount, unionCount);

    return "appx(" + word1 + ", " + word2 + ") = " + (commonCount / gcd) + "/" + (unionCount / gcd);
}

