    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    // Use a set to store possible averages for subsets of size k
    boolean[][] seen = new boolean[n + 1][totalSum + 1];
    for (int i = 0; i <= n; i++) {
        seen[i][0] = true;
    }

    for (int i = 1; i <= n; i++) {
        for (int j = totalSum; j >= nums[i - 1]; j--) {
            for (int k = 1; k <= i; k++) {
