    Set<String> seen = new HashSet<>();
    int totalCombinations = 1 << k; // 2^k

    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);
        seen.add(substring);
        if (seen.size() == totalCombinations) {
            return true;
        }
    }

    return seen.size() == totalCombinations;
}

