public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new LinkedList<>();
        if (low > high) {
            return result;
        }

        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i <= 9; i++) {
            if (i >= low && i <= high) {
                result.add(i);
            }
            if (i == 0 || i == 9) {
                continue;
            }
            queue.add(i);
        }

        while (!queue.isEmpty()) {
            int current = queue.poll();
            if (current > high) {
                continue;
            }
            int lastDigit = current % 10;
            if (lastDigit > 0) {
                int next = current * 10 + lastDigit - 1;
                if (next <= high) {
                    result.add(next);
                    queue.add(next);
                }
            }
            if (lastDigit < 9) {
                int next = current * 10 + lastDigit + 1;
                if (next <= high) {
                    result.add(next);
                    queue.add(next);
                }
            }
        }

        result.sort(Integer::compareTo);
        return result;
    }

