public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int longest = 0;

    // Arrays to store the length of continuous lines
    int[] horizontal = new int[n];
    int[] vertical = new int[m];
    int[] diagonal = new int[n];
    int[] antiDiagonal = new int[n];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Horizontal line
                horizontal[j] = j == 0 ? 1 : horizontal[j - 1] + 1;
                // Vertical line
                vertical[i] = i == 0 ? 1 : vertical[i - 1] + 1;
                // Diagonal line
                diagonal[j] = (i > 0 && j > 0) ? diagonal[j - 1] + 1 : 1;
                // Anti-diagonal line
                antiDiagonal[j] = (i > 0 && j < n - 1) ? antiDiagonal[j + 1] + 1 : 1;

                // Update the longest line found
                longest = Math.max(longest, horizontal[j]);
                longest = Math.max(longest, vertical[i]);
                longest = Math.max(longest, diagonal[j]);
                longest = Math.max(longest, antiDiagonal[j]);
            } else {
                // Reset the lengths if the current cell is 0
                horizontal[j] = 0;
                vertical[i] = 0;
                diagonal[j] = 0;
                antiDiagonal[j] = 0;
            }
        }
    }

    return longest;
}

