    StringBuilder result = new StringBuilder();
    boolean needSeparator = false;

    for (int i = String.valueOf(n).length() - 1; i >= 0; i--) {
        result.append(n % 10);
        n /= 10;

        if (needSeparator && i > 0) {
            result.append('.');
