public static int squarePermutations(int[] A) {
        int n = A.length;
        if (n == 0) return 0;

        boolean[][] graph = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int sum = A[i] + A[j];
                int root = (int) Math.sqrt(sum);
                if (root * root == sum) {
                    graph[i][j] = graph[j][i] = true;
                }
            }
        }

        boolean[] visited = new boolean[n];
        int count = 0;

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                count += dfs(graph, visited, i, 1);
            }
        }

        return count;
    }

