    int r = 0, c = 0, i = 0;

    while (i < result.length) {
        result[i++] = mat[r][c];
        if ((r + c) % 2 == 0) {
            if (c == numCols - 1) {
                r++;
            } else if (r == 0) {
                c++;
            } else {
                r--;
                c++;
            }
        } else {
            if (r == numRows - 1) {
                c++;
            } else if (c == 0) {
                r++;
            } else {
                r++;
                c--;
            }
        }
    }

